import pytest
from mdinline import render


# ===== Basic Emphasis Tests =====

class TestBasicEmphasis:
    """Test single and double asterisk emphasis."""

    def test_single_asterisk_emphasis(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_double_asterisk_strong(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_triple_asterisk(self):
        # ***text*** = strong + em
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_mixed_emphasis_and_strong(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_nested_emphasis(self):
        # **bold *and* italic**
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_nested_strong_inside_em(self):
        assert render("*normal **strong** text*") == "<em>normal <strong>strong</strong> text</em>"

    def test_em_inside_strong(self):
        assert render("**bold *italic* bold**") == "<strong>bold <em>italic</em> bold</strong>"

    def test_unmatched_single_asterisk(self):
        # Unmatched markers stay as text
        assert render("*hello") == "*hello"

    def test_unmatched_double_asterisk(self):
        assert render("hello**") == "hello**"

    def test_multiple_asterisks(self):
        # ****text**** = ** strong + ** strong
        assert render("****text****") == "<strong><strong>text</strong></strong>"

    def test_asterisk_with_space_no_emphasis(self):
        # * hello * - should not be emphasis due to spaces
        assert render("* hello *") == "* hello *"


# ===== Underscore Emphasis Tests =====

class TestUnderscoreEmphasis:
    """Test underscore emphasis with word-boundary rules."""

    def test_single_underscore_emphasis(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_double_underscore_strong(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_underscore_no_emphasis_in_word(self):
        # snake_case_name should NOT have emphasis
        assert render("snake_case_name") == "snake_case_name"

    def test_underscore_no_emphasis_between_words(self):
        # _word1_word2 - no emphasis inside word
        assert render("word_one_word") == "word_one_word"

    def test_underscore_emphasis_at_boundaries(self):
        # _word_ at start/end should work
        assert render("_start_ middle _end_") == "<em>start</em> middle <em>end</em>"

    def test_underscore_before_punctuation(self):
        # _text_. - this should work
        assert render("_hello_.") == "<em>hello</em>."

    def test_triple_underscore(self):
        assert render("___hello___") == "<em><strong>hello</strong></em>"

    def test_underscore_after_punctuation(self):
        assert render("._hello_") == ".<em>hello</em>"


# ===== Code Span Tests =====

class TestCodeSpans:
    """Test backtick code spans."""

    def test_single_backtick_code(self):
        assert render("`code`") == "<code>code</code>"

    def test_code_with_asterisks(self):
        # Emphasis inside code should not be rendered
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_double_backtick_code(self):
        assert render("``code``") == "<code>code</code>"

    def test_code_with_single_backtick_inside(self):
        # ``a ` b`` contains single backtick
        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_triple_backtick_code(self):
        assert render("```code```") == "<code>code</code>"

    def test_code_with_spaces_stripped(self):
        # Space trimming: ` code ` → code
        assert render("` code `") == "<code>code</code>"

    def test_code_with_multiple_spaces_not_stripped(self):
        # Only if starts and ends with space AND is not all spaces
        assert render("`  code  `") == "<code> code </code>"

    def test_code_only_spaces_no_trim(self):
        # All spaces - no trimming
        assert render("`   `") == "<code>   </code>"

    def test_code_unmatched_backtick(self):
        # If no matching backtick, it's plain text
        assert render("text `code without end") == "text `code without end"

    def test_code_binds_tighter_than_emphasis(self):
        # *a `*` b* should be <em>a <code>*</code> b</em>
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

    def test_code_multiple_spans(self):
        assert render("`first` and `second`") == "<code>first</code> and <code>second</code>"

    def test_code_with_html_chars(self):
        # & < > " inside code should be escaped
        assert render("`a & b < c`") == "<code>a &amp; b &lt; c</code>"


# ===== Backslash Escape Tests =====

class TestBackslashEscapes:
    """Test backslash escapes for punctuation."""

    def test_escape_asterisk(self):
        assert render("\\*not emphasis\\*") == "*not emphasis*"

    def test_escape_underscore(self):
        assert render("\\_no\\_emphasis\\_") == "_no_emphasis_"

    def test_escape_backtick(self):
        assert render("\\`not code\\`") == "`not code`"

    def test_escaped_asterisk_prevents_emphasis(self):
        # \*text\* should not create emphasis
        assert render("\\*text\\*") == "*text*"

    def test_escape_other_punctuation(self):
        # Test various ASCII punctuation
        assert render("\\!\\@\\#\\$") == "!@#$"

    def test_backslash_before_non_punctuation(self):
        # Backslash before non-punctuation is literal
        assert render("\\a\\b\\c") == "\\a\\b\\c"

    def test_backslash_at_end(self):
        # Backslash at end of line is literal
        assert render("text\\") == "text\\"

    def test_escape_inside_code_no_effect(self):
        # Inside code spans, backslashes are literal
        assert render("`\\*not escaped`") == "<code>\\*not escaped</code>"

    def test_escaped_backtick_not_code_delimiter(self):
        # \` ` is not a code span
        assert render("\\` text `") == "` text `"


# ===== HTML Escaping Tests =====

class TestHTMLEscaping:
    """Test HTML entity escaping."""

    def test_escape_ampersand(self):
        assert render("a & b") == "a &amp; b"

    def test_escape_less_than(self):
        assert render("a < b") == "a &lt; b"

    def test_escape_greater_than(self):
        assert render("a > b") == "a &gt; b"

    def test_escape_quote(self):
        assert render('a "b" c') == 'a &quot;b&quot; c'

    def test_escape_multiple_chars(self):
        assert render("a < b & c") == "a &lt; b &amp; c"

    def test_escape_in_code_span(self):
        assert render("`a & b < c`") == "<code>a &amp; b &lt; c</code>"

    def test_escape_in_emphasis(self):
        assert render("*a & b*") == "<em>a &amp; b</em>"

    def test_escape_in_strong(self):
        assert render("**a < b**") == "<strong>a &lt; b</strong>"

    def test_no_other_escape(self):
        # Only &, <, >, " should be escaped
        assert render("a | b % c") == "a | b % c"


# ===== Input Validation Tests =====

class TestInputValidation:
    """Test input validation."""

    def test_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\ntwo")

    def test_carriage_return_raises_error(self):
        with pytest.raises(ValueError):
            render("one\rtwo")

    def test_carriage_return_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\r\ntwo")

    def test_valid_empty_string(self):
        # Empty string is valid
        assert render("") == ""

    def test_valid_single_char(self):
        assert render("a") == "a"

    def test_valid_whitespace(self):
        # Spaces and tabs are ok
        assert render("a\tb  c") == "a\tb  c"


# ===== Delimiter Run Matching Tests =====

class TestDelimiterRunMatching:
    """Test delimiter run matching rules."""

    def test_modulo_3_rule_both_even(self):
        # Even runs with both > 1 can't match if sum is multiple of 3
        # **foo**bar* - **bar* matches first **, result: <strong>foo</strong>bar*
        assert render("**foo**bar*") == "<strong>foo</strong>bar*"

    def test_modulo_3_rule_different_lengths(self):
        # *foo**bar* - different lengths, should match the first *
        result = render("*foo**bar*")
        # * at start and end have length 1 each, sum = 2 (not multiple of 3)
        # They should match, result: <em>foo**bar</em>
        assert result == "<em>foo**bar</em>"

    def test_longer_run_leftover(self):
        # **a* becomes *<em>a</em>
        result = render("**a*")
        # ** can open, * can close, they match (taking 1 from each)
        # Leftover * becomes plain text
        assert result == "*<em>a</em>"

    def test_longer_run_leftover_multiple(self):
        # ***a*** = <em><strong>a</strong></em>
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_greedy_matching_left_to_right(self):
        # Matching goes left to right over closers
        result = render("*a*b*c*")
        # First closer after a is *, matches first *
        # Result: <em>a</em>b<em>c</em>
        assert result == "<em>a</em>b<em>c</em>"


# ===== Edge Cases and Special Scenarios =====

class TestEdgeCases:
    """Test edge cases and special scenarios."""

    def test_only_whitespace(self):
        assert render("   ") == "   "

    def test_leading_trailing_whitespace_preserved(self):
        assert render("  text  ") == "  text  "

    def test_tab_characters(self):
        assert render("a\tb\tc") == "a\tb\tc"

    def test_form_feed(self):
        # Form feed is whitespace
        assert render("a\fb") == "a\fb"

    def test_no_break_space(self):
        # U+00A0 no-break space is whitespace
        assert render("a\u00a0b") == "a\u00a0b"

    def test_ideographic_space(self):
        # U+3000 ideographic space is whitespace
        assert render("a\u3000b") == "a\u3000b"

    def test_emphasis_with_leading_space(self):
        # * hello* where before is space
        # * is not left-flanking
        assert render("* hello*") == "* hello*"

    def test_emphasis_with_trailing_space(self):
        # *hello * where after is space
        # * is not right-flanking
        assert render("*hello *") == "*hello *"

    def test_consecutive_emphasis_spans(self):
        assert render("*a* *b* *c*") == "<em>a</em> <em>b</em> <em>c</em>"

    def test_consecutive_code_spans(self):
        assert render("`a` `b` `c`") == "<code>a</code> `b` `c`"
        # Actually, let me check - backticks match by count
        # First ` and second ` should match
        # But if they're separated by space and content
        # `a` matches, then `b` matches, then `c` matches
        # Actually the second backtick after `a` matches it
        # So `a` is <code>a</code>, then space, then `b` - no match yet
        # Then `c` - still no match for b
        # So it should be `<code>a</code> ` ` ` `c` `
        # Wait, I need to think about this more carefully
        # In "`a` `b` `c`":
        # Backtick 1 opens code span
        # a is content
        # Backtick 2 closes (same count as opener)
        # Result so far: `<code>a</code> `
        # Then `b` - backtick 3 opens
        # b is content
        # Backtick 4 closes
        # Result so far: `<code>a</code> <code>b</code> `
        # Then `c` - backtick 5 opens
        # c is content  
        # No more backticks, so this is unmatched
        # Result: `<code>a</code> <code>b</code> `c` `
        # Hmm, but let me reconsider. Actually:
        # `a` - backtick count 1, matches → <code>a</code>
        # ` ` - backtick count 1, opens (since there's no content between consecutive backticks)
        # Wait no, it's `<space>` which is backtick + space = not content
        # Let me re-read: backtick + space. The backtick opens a potential code span.
        # Next backtick is `b`. That's after space. 
        # For a span to close, it needs the same count. Count after first ` in " `" is 1.
        # Next backtick in "`b`" - what's its count? It's just one backtick.
        # Does it close? Let me count: ` (opens, count=1), b (content), ` (count=1, closes!)
        # So " `b` " is <space><code>b</code><space>
        # Then "`c`" is <code>c</code>
        # Result: `<code>a</code> <code>b</code> <code>c</code>`
        # Let me verify with spec: "A code span starts with a backtick string and ends with 
        # the next backtick string of exactly the same length."
        # First ` in "`a` `b` `c`" opens with count 1
        # Next backtick is after a - that's count 1, closes → `<code>a</code>`
        # Next backtick is after space - that's count 1, opens new span
        # Next backtick is after b - that's count 1, closes → `<code>b</code>`
        # Next backtick is after space - that's count 1, opens new span
        # Next backtick is after c - that's count 1, closes → `<code>c</code>`
        # So result should be: `<code>a</code> <code>b</code> <code>c</code>`
        assert render("`a` `b` `c`") == "<code>a</code> <code>b</code> <code>c</code>"

    def test_emphasis_in_multiple_spans(self):
        assert render("*a* b *c*") == "<em>a</em> b <em>c</em>"

    def test_mixed_emphasis_and_code(self):
        assert render("*italic* `code` **bold**") == "<em>italic</em> <code>code</code> <strong>bold</strong>"

    def test_emphasis_start_with_punctuation(self):
        # *text where before is punctuation
        result = render("(*text*)")
        # ( is punctuation, before the first *
        # First * is left-flanking if after is not whitespace
        # and either after is not punct or before is whitespace or punct
        # after is t (not whitespace, not punct) → left-flanking OK
        # before is ( (punctuation) → left-flanking OK
        assert result == "(<em>text</em>)"

    def test_code_no_space_start_no_trim(self):
        # `code` with no leading space
        assert render("`code`") == "<code>code</code>"

    def test_code_space_only_one_end_no_trim(self):
        # ` code` with space only at start - still needs both ends
        assert render("` code`") == "<code> code</code>"

    def test_code_text_space_start_and_end(self):
        # ` text ` with space at both ends
        assert render("` text `") == "<code>text</code>"

    def test_code_many_spaces_start_and_end(self):
        # `  text  ` with multiple spaces
        assert render("`  text  `") == "<code> text </code>"

    def test_backtick_different_counts(self):
        # `` `text` `` - outer has count 2, inner has count 1
        # Outer backticks match
        result = render("`` `text` ``")
        assert result == "<code>`text`</code>"

    def test_em_then_strong_separate(self):
        # *a* **b** should be <em>a</em> <strong>b</strong>
        assert render("*a* **b**") == "<em>a</em> <strong>b</strong>"


# ===== CommonMark Examples from Readme =====

class TestReadmeExamples:
    """Test examples from README.md."""

    def test_example_1(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_example_2(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_example_3(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_example_4(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"
